18	        let attrs = input.call(syn::Attribute::parse_outer)?;
19	        let token = input.parse()?;
20	        let name = input.parse()?;
21	
22	        let content;
23	        syn::braced!(content in input);
24	        let mut methods = vec![];
25	        let mut properties = vec![];
26	
