3	pub fn format(input: &str) -> String {
4	    let stream: TokenStream = input.parse().unwrap_or_default();
5	    let tokens: Vec<TokenTree> = stream.into_iter().collect();
6	    let mut output = String::new();
7	    format_seq(&tokens, &mut output, 0, false);
8	    output
9	}
10	
11	fn format_seq(tokens: &[TokenTree], output: &mut String, indent: usize, inline: bool) {
12	    let mut i = 0;
13	    let mut angle_depth: usize = 0;
14	
15	    while i < tokens.len() {
16	        // Detect outer attribute: `#` followed by a `[...]` group.
17	        if let TokenTree::Punct(p) = &tokens[i] {
18	            if p.as_char() == '#' {
19	                if let Some(TokenTree::Group(g)) = tokens.get(i + 1) {
20	                    if g.delimiter() == Delimiter::Bracket {
21	                        // An attribute that immediately follows `->` is a return-type
22	                        // attribute and must stay inline (e.g. `-> #[Const] *const u8`).
23	                        let after_arrow = output.ends_with("-> ");
24	                        let treat_inline = inline || after_arrow;
25	                        if !treat_inline && at_line_start(output) {
26	                            push_indent(output, indent);
27	                        }
28	                        format_attribute(g, output);
29	                        if treat_inline {
30	                            output.push(' ');
31	                        } else {
32	                            output.push('\n');
33	                        }
34	                        i += 2;
35	                        continue;
36	                    }
37	                }
38	            }
39	        }
40	
41	        if !inline && at_line_start(output) {
42	            push_indent(output, indent);
43	        }
44	
45	        match &tokens[i] {
46	            TokenTree::Ident(id) => {
47	                output.push_str(&id.to_string());
48	                output.push(' ');
49	            }
50	            TokenTree::Literal(lit) => {
51	                output.push_str(&lit.to_string());
52	                output.push(' ');
53	            }
54	            TokenTree::Punct(p) => match (p.as_char(), p.spacing()) {
55	                (':', Spacing::Joint) => {
56	                    trim_space(output);
57	                    output.push_str("::");
58	                    i += 1; // skip the second `:`
59	                }
60	                (':', _) => {
61	                    trim_space(output);
62	                    output.push_str(": ");
63	                }
64	                (',', _) => {
65	                    trim_space(output);
66	                    output.push(',');
67	                    if inline || angle_depth > 0 {
68	                        output.push(' ');
69	                    } else {
70	                        output.push('\n');
71	                    }
72	                }
73	                (';', _) => {
74	                    trim_space(output);
75	                    output.push(';');
76	                    if inline {
77	                        output.push(' ');
78	                    } else {
79	                        output.push('\n');
80	                    }
81	                }
82	                // Single member-access dot: trim the preceding space.
83	                // Joint dots are part of `...` (variadic) and must not trim
84	                // the preceding space so that `, ...` formats correctly.
85	                ('.', Spacing::Alone) => {
86	                    trim_space(output);
87	                    output.push('.');
88	                }
89	                ('.', _) => output.push('.'),
90	                // `->` return-type arrow
91	                ('-', Spacing::Joint) => {
92	                    output.push_str("-> ");
93	                    i += 1; // skip the `>`
94	                }
95	                ('-', _) => output.push('-'),
96	                ('*', _) => output.push('*'),
97	                ('&', _) => output.push('&'),
98	                ('+', _) => {
99	                    trim_space(output);
100	                    output.push_str(" + ");
101	                }
102	                ('=', _) => {
103	                    trim_space(output);
104	                    output.push_str(" = ");
105	                }
106	                ('|', _) => {
107	                    trim_space(output);
108	                    output.push_str(" | ");
109	                }
110	                ('<', _) => {
111	                    trim_space(output);
112	                    output.push('<');
113	                    angle_depth = angle_depth.saturating_add(1);
114	                }
115	                ('>', _) => {
116	                    trim_space(output);
117	                    output.push('>');
118	                    angle_depth = angle_depth.saturating_sub(1);
119	                }
120	                _ => output.push(p.as_char()),
121	            },
122	            TokenTree::Group(g) => match g.delimiter() {
123	                Delimiter::Brace => {
124	                    let inner: Vec<TokenTree> = g.stream().into_iter().collect();
125	                    if inner.is_empty() {
126	                        output.push_str("{}\n");
127	                    } else {
128	                        if !output.ends_with(' ') {
129	                            output.push(' ');
130	                        }
131	                        output.push_str("{\n");
132	                        format_seq(&inner, output, indent + 1, false);
133	                        push_indent(output, indent);
134	                        output.push('}');
135	                        if matches!(tokens.get(i + 1), Some(TokenTree::Punct(p)) if p.as_char() == ',')
136	                        {
137	                            output.push_str(",\n");
138	                            i += 1; // skip the `,`
139	                        } else {
140	                            output.push('\n');
141	                        }
142	                    }
143	                }
144	                Delimiter::Parenthesis => {
145	                    trim_space(output);
146	                    output.push('(');
147	                    let inner: Vec<TokenTree> = g.stream().into_iter().collect();
148	                    format_seq(&inner, output, indent, true);
149	                    trim_space(output);
150	                    output.push_str(") ");
151	                }
152	                Delimiter::Bracket => {
153	                    output.push('[');
154	                    let inner: Vec<TokenTree> = g.stream().into_iter().collect();
155	                    format_seq(&inner, output, indent, true);
156	                    trim_space(output);
157	                    output.push(']');
158	                }
159	                _ => {}
160	            },
161	        }
162	
163	        i += 1;
164	    }
165	}
166	
167	fn format_attribute(g: &Group, output: &mut String) {
168	    output.push_str("#[");
169	    let inner: Vec<TokenTree> = g.stream().into_iter().collect();
170	    format_seq(&inner, output, 0, true);
171	    trim_space(output);
172	    output.push(']');
173	}
174	
175	fn at_line_start(output: &str) -> bool {
176	    output.ends_with('\n') || output.is_empty()
177	}
178	
179	fn push_indent(output: &mut String, level: usize) {
180	    for _ in 0..level {
181	        output.push_str("    ");
182	    }
183	}
184	
185	fn trim_space(output: &mut String) {
186	    if output.ends_with(' ') {
187	        output.pop();
188	    }
189	}
