12	/// Compile `rdl` to a temp `.winmd` file (panicking on failure) and return the path.
13	fn compile_to_winmd(rdl: &str, extra_input: Option<&str>) -> std::path::PathBuf {
14	    let n = COUNTER.fetch_add(1, Ordering::Relaxed);
15	    let path = std::env::temp_dir().join(format!("rdl_panic_{}_{n}.winmd", std::process::id()));
