#[derive(Debug)]
pub struct Interface {
    pub attrs: Vec<syn::Attribute>,
    pub token: interface,
    pub name: syn::Ident,
    pub generics: syn::Generics,
    pub requires: Vec<syn::Path>,
    pub members: Vec<InterfaceMember>,
    pub winrt: bool,
}

/// A member declared inside an interface body: a regular method, a property
/// shorthand, or an event shorthand.
#[derive(Debug)]
pub enum InterfaceMember {
    Method(Method),
    Property(Property),
    Event(Event),
}

/// A property shorthand declaration inside an interface body.
///
/// Parsed from `[#[get] | #[set]] Name: Type;`.  Without any attribute both a
/// getter and a setter are generated; with `#[get]` only a getter is generated;
/// with `#[set]` only a setter is generated.
#[derive(Debug)]
pub struct Property {
    pub attrs: Vec<syn::Attribute>,
    pub name: syn::Ident,
    pub ty: syn::Type,
}

/// An event shorthand declaration inside a WinRT interface body.
///
/// Parsed from `event Name: HandlerType;`.  Generates `add_Name`/`remove_Name`
/// method pairs with the `SpecialName` flag.
#[derive(Debug)]
pub struct Event {
    pub name: syn::Ident,
    pub handler_ty: syn::Type,
}

impl syn::parse::Parse for InterfaceMember {
    fn parse(input: syn::parse::ParseStream) -> syn::Result<Self> {
        if input.peek(event) {
            return Ok(InterfaceMember::Event(input.parse()?));
        }

        let attrs = input.call(syn::Attribute::parse_outer)?;

        if input.peek(syn::Token![fn]) {
            Ok(InterfaceMember::Method(Method::parse_with_attrs(
                input, attrs,
            )?))
        } else {
            Ok(InterfaceMember::Property(Property::parse_with_attrs(
                input, attrs,
            )?))
        }
    }
}

impl Property {
    fn parse_with_attrs(
        input: syn::parse::ParseStream,
        attrs: Vec<syn::Attribute>,
    ) -> syn::Result<Self> {
        let mut get_attr = None;
        let mut set_attr = None;

        for attr in &attrs {
            if attr.path().is_ident("get") {
                get_attr = Some(attr);
            } else if attr.path().is_ident("set") {
                set_attr = Some(attr);
            } else {
                return Err(syn::Error::new_spanned(
                    attr,
                    "only `#[get]` and `#[set]` attributes are supported on properties",
                ));
            }
        }

        if let (Some(_), Some(set_attr)) = (get_attr, set_attr) {
            return Err(syn::Error::new_spanned(
                set_attr,
                "property cannot have both `#[get]` and `#[set]` attributes",
            ));
        }

        let name = input.parse()?;
        input.parse::<syn::Token![:]>()?;
        let ty = input.parse()?;
        input.parse::<syn::Token![;]>()?;

        Ok(Self { attrs, name, ty })
    }
}

impl syn::parse::Parse for Event {
    fn parse(input: syn::parse::ParseStream) -> syn::Result<Self> {
        input.parse::<event>()?;
        let name = input.parse()?;
        input.parse::<syn::Token![:]>()?;
        let handler_ty = input.parse()?;
        input.parse::<syn::Token![;]>()?;

        Ok(Self { name, handler_ty })
    }
}

