        already_has_guid: bool,
        method_signatures: &mut Vec<(String, Vec<metadata::Type>, metadata::Type)>,
    ) -> Result<(), Error> {
        let types: Vec<metadata::Type> = params.iter().map(|(_, ty)| (*ty).clone()).collect();

        if !already_has_guid {
            method_signatures.push((name.to_string(), types.clone(), return_type.clone()));
