        for arg in &sig.inputs {
            match arg {
                syn::FnArg::Receiver(receiver) => {
                    return self.err(receiver, "unexpected `self` parameter");
                }
                syn::FnArg::Typed(pt) => {
                    let syn::Pat::Ident(ref name) = *pt.pat else {
