pub fn write_interface(item: &metadata::reader::TypeDef) -> Result<TokenStream, Error> {
    let namespace = item.namespace();
    let name = write_ident(item.name());

    let (generics, generics_tokens) = write_generic_params(item);

    let methods = write_members(namespace, item, &generics)?;

    let requires: Vec<_> = item.interface_impls().collect();

    let requires_tokens = if requires.is_empty() {
        quote! {}
    } else {
        let ifaces = requires
            .iter()
            .map(|imp| write_type(namespace, &imp.interface(&generics)));
        quote! { : #(#ifaces)+* }
    };

    let guid_token = match interface_guid_output(item, &generics)? {
        GuidOutput::None => quote! { #[no_guid] },
        GuidOutput::Omit => quote! {},
        GuidOutput::Explicit(d1, d2, d3, d4) => {
            let lit = syn::LitInt::new(&format_guid_u128(d1, d2, d3, d4), Span::call_site());
            quote! { #[guid(#lit)] }
        }
    };
    let custom_attrs = write_custom_attributes_except(
        item.attributes(),
        namespace,
        item.index(),
        &["GuidAttribute"],
    )?;

    Ok(quote! {
        #guid_token
        #(#custom_attrs)*
        interface #name #generics_tokens #requires_tokens {
            #(#methods)*
        }
    })
}

/// Emits all interface members, converting `SpecialName` getter/setter method pairs to
/// property shorthand (`Name: Type;`), `SpecialName` add/remove method pairs to event
/// shorthand (`event Name: HandlerType;`), and falling back to the regular method
/// representation for any method that is not consumed as part of such a pair.
fn write_members(
    namespace: &str,
    item: &metadata::reader::TypeDef,
    generics: &[metadata::Type],
) -> Result<Vec<TokenStream>, Error> {
    let methods: Vec<metadata::reader::MethodDef> = item.methods().collect();
    let mut consumed = vec![false; methods.len()];
    let mut members = Vec::new();

    for i in 0..methods.len() {
        if consumed[i] {
            continue;
        }

        let method = &methods[i];
        let is_special = method
            .flags()
            .contains(metadata::MethodAttributes::SpecialName);

        if is_special {
            let name = method.name();

            if let Some(prop) = name.strip_prefix("get_") {
                consumed[i] = true;
                let prop_ident = write_ident(prop);
                let ty = write_type(namespace, &method.signature(generics).return_type);

                let setter =
                    find_unconsumed(&methods, &consumed, i, &format!("put_{prop}")).filter(|&j| {
                        methods[j]
                            .flags()
                            .contains(metadata::MethodAttributes::SpecialName)
                    });

                if let Some(j) = setter {
                    consumed[j] = true;
                    // Both getter and setter present: read-write property.
                    members.push(quote! { #prop_ident: #ty; });
                } else {
                    // Getter only: read-only property.
                    members.push(quote! { #[get] #prop_ident: #ty; });
                }
                continue;
            }

            if let Some(prop) = name.strip_prefix("put_") {
                consumed[i] = true;
                let prop_ident = write_ident(prop);
                let signature = method.signature(generics);
                let ty = write_type(namespace, &signature.types[0]);
                // Setter only: write-only property.
                members.push(quote! { #[set] #prop_ident: #ty; });
                continue;
            }

            if let Some(ev) = name.strip_prefix("add_") {
                consumed[i] = true;
                let ev_ident = write_ident(ev);
                let signature = method.signature(generics);
                let handler_ty = write_type(namespace, &signature.types[0]);

                if let Some(j) = find_unconsumed(&methods, &consumed, i, &format!("remove_{ev}"))
                    .filter(|&j| {
                        methods[j]
                            .flags()
                            .contains(metadata::MethodAttributes::SpecialName)
                    })
                {
                    consumed[j] = true;
                }

                members.push(quote! { event #ev_ident: #handler_ty; });
                continue;
            }
        }

        consumed[i] = true;
        members.push(write_method(namespace, method, generics)?);
    }

    Ok(members)
}

